<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Menü yönetimi</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:16px 0}input,select{padding:10px;border:1px solid #dfe6e0;border-radius:8px;font:inherit;margin:5px}button{background:#176b50;color:white;border:0;border-radius:8px;padding:10px 14px;font-weight:700}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #edf0ed}</style></head><body><main class="wrap"><h1>Menü yönetimi</h1><section class="panel"><h2>Yeni menü bağlantısı</h2><form method="post" action="/admin/navigation/save"><?= csrf_field() ?><input name="label" placeholder="Menü adı" required><input name="url" placeholder="/sayfa veya https://..." required><select name="location"><option value="header">Üst menü</option><option value="footer">Alt menü</option></select><select name="target"><option value="_self">Aynı sekme</option><option value="_blank">Yeni sekme</option></select><input type="number" name="sort_order" value="10" style="width:80px"><button>Bağlantıyı ekle</button></form></section><section class="panel"><table><thead><tr><th>Menü adı</th><th>Bağlantı</th><th>Konum</th><th>Sıra</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['label']) ?></td><td><?= e($item['url']) ?></td><td><?= e($item['location']) ?></td><td><?= (int)$item['sort_order'] ?></td><td><?= (int)$item['is_active']?'Aktif':'Pasif' ?></td><td><form method="post" action="/admin/navigation/delete"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button type="submit" style="background:#a43">Sil</button></form></td></tr><?php endforeach; ?></tbody></table></section><p><a href="/admin">Yönetim paneli</a></p></main></body></html>